--- globals for `midnight lint`: the configured ones, rest's (in rest projects),
--- and the buffer's (vim.b.midnight_globals)
---@param buf? integer
---@return string[]
function _MODULE.globals(buf) if buf == nil then buf = vim.api.nvim_get_current_buf() end
  local names = vim.deepcopy(_MODULE.config.globals)
  if _MODULE.config.rest and require("midnight.rest").in_project(buf) then
    vim.list_extend(names, require("midnight.rest").globals)
  end
  local __MIDNIGHT_TMP_11__ if _MODULE.config.nvim == true then __MIDNIGHT_TMP_11__ = _MODULE.is_nvim else __MIDNIGHT_TMP_11__ = _MODULE.config.nvim end local nvim = __MIDNIGHT_TMP_11__
  if nvim and nvim(buf) then names[#names + 1] = "vim" end
  return vim.list_extend(names, vim.b[buf].midnight_globals or {})
end


local runtime_dirs = (table.freeze({
lua = true, 
plugin = true, 
ftplugin = true, 
after = true, 
autoload = true, 
indent = true, 
syntax = true, 
colors = true, 
compiler = true
}))

--- is buf neovim code? Files in your config (stdpath('config')), in a
--- runtime directory (lua/, plugin/, ftplugin/, after/, ...) of a project with
--- a lua/ directory, ie. a plugin (ex. foo.nvim/lua/foo/init.mn), and anywhere
--- in a project whose midnight.json is next to a lua/ directory (a plugin w/
--- its midnight sources elsewhere, ex. foo.nvim/midnight/foo/init.mn)
---@param buf integer
---@return boolean
function _MODULE.is_nvim(buf)
  local name = vim.api.nvim_buf_get_name(buf)
  if name == "" then return false end
  local path = vim.uv.fs_realpath(name) or vim.fs.normalize(name)

  local config_dir = vim.uv.fs_realpath(vim.fn.stdpath("config"))
  if config_dir and vim.startswith(path, tostring(config_dir) .. "/") then return true end

  for dir in vim.fs.parents(path) do
    if runtime_dirs[vim.fs.basename(dir)] then
      local stat = vim.uv.fs_stat(tostring(vim.fs.dirname(dir)) .. "/lua")
      if stat and stat.type == "directory" then return true end
    end
  end

  local project = vim.fs.root(path, "midnight.json")
  if project then
    local stat = vim.uv.fs_stat(tostring(project) .. "/lua")
    if stat and stat.type == "directory" then return true end
  end
  return false
end

