--- `<stdin>:12: message (rule)` -> diagnostics
---@param output string
---@return vim.Diagnostic[]
function _MODULE.parse_lint(output)
  local diagnostics = {}
  for line in vim.gsplit(output, "\n", {trimempty = true}) do
    local lnum, message, rule = line:match("^[^:]+:(%d+): (.+) %(([%w-]+)%)$")
    if lnum then
      diagnostics[#diagnostics + 1] = {
      lnum = tonumber(lnum) - 1, 
      col = 0, 
      message = message, 
      code = rule, 
      source = "midnight lint", 
      severity = ((function() if rule == "syntax" then return vim.diagnostic.severity.ERROR else return 
          vim.diagnostic.severity.WARN
        end end)())
      }
    end
  end
  return diagnostics
end

--- nvim-lint linter (a function, so the args are built for each run)
function _MODULE.linter()
  return function()
    local args = vim.list_extend({"lint"}, _MODULE.factory_args())
    local names = _MODULE.globals()
    if #names > 0 then vim.list_extend(args, {"-g", table.concat(names, ",")}) end
    args[#args + 1] = "-"
    return {
    cmd = _MODULE.config.cmd, 
    args = args, 
    stdin = true, 
    ignore_exitcode = true, 
    parser = function(output) return _MODULE.parse_lint(output) end
    }
  end
end

--- `midnight -c` the buffer, ie. the lua it compiles to
---@param buf integer
---@return string[]? lines, string? err
function _MODULE.compile(buf)
  local src = table.concat(vim.api.nvim_buf_get_lines(buf, 0, -1, false), "\n")
  local cmd = vim.list_extend({_MODULE.config.cmd}, _MODULE.factory_args())
  vim.list_extend(cmd, {"-c", "-"})
  local res = vim.system(cmd, {stdin = src, text = true}):wait()
  if res.code ~= 0 then return nil, vim.trim((res.stderr or "") .. (res.stdout or "")) end
  return vim.split(res.stdout, "\n", {trimempty = false})
end

--- compiles buf's file into its project's compile.out (see config.compile),
--- if it's in a project w/ a midnight.json. On success it shows a quiet
--- "compiled ..." notice (config.compile_notify) only when the output changed;
--- errors use vim.notify.
---@param buf? integer
function _MODULE.compile_file(buf) if buf == nil then buf = vim.api.nvim_get_current_buf() end
  local root = vim.fs.root(buf, "midnight.json")
  if not root then return end
  local cmd = vim.list_extend({_MODULE.config.cmd, "compile", "-project"}, _MODULE.factory_args())
  cmd[#cmd + 1] = vim.api.nvim_buf_get_name(buf)
  vim.system(cmd, {cwd = root, text = true}, function(res)
    vim.schedule(function()
      if res.code ~= 0 then
        local msg = vim.trim((res.stdout or "") .. (res.stderr or ""))
        return vim.notify(msg, vim.log.levels.ERROR, {title = "midnight compile"})
      end
      _MODULE.compile_notify(buf, root, res.stdout)
    end)
  end)
end

--- the "compiled ..." notice after a write (config.compile_notify). It only
--- shows when the compiled output actually changed since the last compile, so
--- saving w/o edits stays quiet. fidget.nvim's corner window if it's installed,
--- else vim.notify; a shared `key` reuses fidget's last notice instead of
--- stacking them.
---@param buf integer
---@param root string
---@param stdout string
function _MODULE.compile_notify(buf, root, stdout)
  if not _MODULE.config.compile_notify then return end



  local out = stdout and stdout:match("=>%s*(%S+)")
  if out then
    if not (out:match("^/") or out:match("^%a:[/\\]") or out:match("^\\\\")) then
      out = vim.fs.joinpath(root, out)
    end
    local path = vim.fs.normalize(out)
    local __MIDNIGHT_TMP_26__ do local __MIDNIGHT_TMP_27__, __MIDNIGHT_TMP_28__ = pcall(function() return table.concat(vim.fn.readfile(path), "\n") end) if __MIDNIGHT_TMP_27__ then __MIDNIGHT_TMP_26__ = __MIDNIGHT_TMP_28__ else __MIDNIGHT_TMP_26__ = nil end end local content = __MIDNIGHT_TMP_26__
    if content and content == _MODULE._compiled[path] then return end
    _MODULE._compiled[path] = content
  end
  local name = vim.api.nvim_buf_get_name(buf)
  local msg = "compiled " .. tostring(vim.fs.relpath(root, name) or name)
  local __MIDNIGHT_TMP_31__ do local __MIDNIGHT_TMP_32__, __MIDNIGHT_TMP_33__ = pcall(require, "fidget") if __MIDNIGHT_TMP_32__ then __MIDNIGHT_TMP_31__ = __MIDNIGHT_TMP_33__ else __MIDNIGHT_TMP_31__ = nil end end local fidget = __MIDNIGHT_TMP_31__
  if fidget and fidget.notify then
    fidget.notify(msg, vim.log.levels.INFO, {key = "midnight.compile", annote = "midnight"}) else

    vim.notify(msg, vim.log.levels.INFO, {title = "midnight compile"})
  end
end

--- shows the compiled lua in a split, kept up to date as the buffer changes
function _MODULE.preview(buf) if buf == nil then buf = vim.api.nvim_get_current_buf() end
  local preview = vim.b[buf].midnight_preview
  if preview and vim.api.nvim_buf_is_valid(preview) then
    local win = vim.fn.bufwinid(preview)
    if win ~= -1 then return vim.api.nvim_set_current_win(win) end
    vim.cmd.vsplit()
    return vim.api.nvim_win_set_buf(0, preview)
  end

  preview = vim.api.nvim_create_buf(false, true)
  vim.bo[preview].bufhidden = "wipe"
  vim.bo[preview].filetype = "lua"
  vim.api.nvim_buf_set_name(preview, "midnight://" .. tostring(vim.api.nvim_buf_get_name(buf)) .. ".lua")
  vim.b[buf].midnight_preview = preview

  local function update()
    local lines, err = _MODULE.compile(buf)
    if not lines then

      lines = vim.list_extend(
      vim.tbl_map(function(l) return "-- " .. tostring(l) end, vim.split(err, "\n")), 
      vim.list_slice(vim.api.nvim_buf_get_lines(preview, 0, -1, false), 1))

    end
    vim.bo[preview].modifiable = true
    vim.api.nvim_buf_set_lines(preview, 0, -1, false, lines)
    vim.bo[preview].modifiable = false
  end

  local group = vim.api.nvim_create_augroup("midnight.preview." .. tostring(buf), {clear = true})
  vim.api.nvim_create_autocmd({"TextChanged", "InsertLeave", "BufWritePost"}, {
  group = group, 
  buffer = buf, 
  callback = function()
    if vim.api.nvim_buf_is_valid(preview) then update() end
  end
  })
  vim.api.nvim_create_autocmd("BufWipeout", {
  group = group, 
  buffer = preview, 
  callback = function()
    pcall(function() return vim.api.nvim_del_augroup_by_id(group) end)
    if vim.api.nvim_buf_is_valid(buf) then vim.b[buf].midnight_preview = nil end
  end
  })

  local src_win = vim.api.nvim_get_current_win()
  vim.cmd.vsplit()
  vim.api.nvim_win_set_buf(0, preview)
  update()
  vim.api.nvim_set_current_win(src_win)
end

--- `gf` on require('src/layout') or require('src.layout')
---@param fname string
function _MODULE.includeexpr(fname)
  if fname:find("/", 1, true) then return fname end
  return fname:gsub("%.", "/")
end
return _MODULE
